        // Disable XInclude processing
        docFactory.setXIncludeAware(false);
        docFactory.setExpandEntityReferences(false);

        // Enable namespace awareness
        docFactory.setNamespaceAware(true);

        // Set additional security attributes
        docFactory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        docFactory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        DocumentBuilder docBuilder = docFactory.newDocumentBuilder();

        // Set a custom entity resolver that prevents external entity resolution
        docBuilder.setEntityResolver((publicId, systemId) -> new InputSource(new StringReader("")));

        try (InputStream inputStream = new FileInputStream(configFile)) {
            return docBuilder.parse(inputStream);
        }
    }
}
